import { useCallback, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";

import { AFTER_STARTUP_DOCS_LINK, PREVIEW_ACTION_NOT_FOUND_ERROR_MESSAGE } from "@src/constants/studioPro";
import { ErrorWithLink } from "@src/types/generic";
import { agentErrorIconBase64 } from "../icons/agentIcons";
import { TestVariable } from "../types/agent";
import { Response } from "../types/playground";
import { executeTestAction } from "../utils/agentUtils";

const ASU_NOT_TRIGGERED_MESSAGE =
    "Please make sure the ASU_AgentEditor is triggered upon app startup in order to register your agent and test it locally.";
const GENERIC_ERROR_MESSAGE = "Test action failed. Please check the runtime logs for more details.";

type UseTestActionResult = {
    data: Response | undefined;
    isPending: boolean;
    isError: boolean;
    error: Error | undefined;
    execute: (testVariables: TestVariable[]) => void;
};

/**
 * Hook that executes an agent test action and manages its async state.
 *
 * @param studioPro - The StudioPro API instance.
 * @param agent - The agent to test.
 * @param isRuntimeConnected - Whether the runtime is currently connected.
 * @returns `data` with the resolved response, `isPending` while executing,
 *          `isError` and `error` on failure, and `execute` to trigger the action.
 */
export const useTestAction = (
    studioPro: StudioProApi,
    documentId: string,
    isRuntimeConnected: boolean
): UseTestActionResult => {
    const [data, setData] = useState<Response | undefined>(undefined);
    const [isPending, setIsPending] = useState(false);
    const [isError, setIsError] = useState(false);
    const [error, setError] = useState<ErrorWithLink | undefined>(undefined);

    const execute = useCallback(
        async (testVariables: TestVariable[]) => {
            if (!isRuntimeConnected) {
                await studioPro.ui.notifications.show({
                    icon: agentErrorIconBase64,
                    title: "App is not running",
                    message: "Please run the app to use the playground.",
                });
                return;
            }

            setIsPending(true);
            setData(undefined);
            setIsError(false);
            setError(undefined);

            try {
                const response = await executeTestAction(studioPro, documentId, testVariables);

                if (response === undefined) {
                    throw new Error("No response received from the test action.");
                }

                if ("message" in response && response.message === PREVIEW_ACTION_NOT_FOUND_ERROR_MESSAGE) {
                    setIsError(true);
                    setError({ name: "Error", message: ASU_NOT_TRIGGERED_MESSAGE, link: AFTER_STARTUP_DOCS_LINK });
                    return;
                }

                setData(response);
            } catch {
                setIsError(true);
                setError({ name: "Error", message: GENERIC_ERROR_MESSAGE });
            } finally {
                setIsPending(false);
            }
        },

        [studioPro, isRuntimeConnected, documentId]
    );

    return { data, isPending, isError, error, execute };
};
