import { useEffect, useMemo, useRef, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";

import { EntityIcon } from "@mendix/ide-icons/EntityIcon";
import { EntityNonPersistableIcon } from "@mendix/ide-icons/EntityNonPersistableIcon";
import { TextArea } from "@mendix/ide-ui-components/input/TextArea";
import { useTheme } from "styled-components";

import { componentName } from "../../main/index";

import { useTestAction } from "../../hooks/useTestAction";
import { Agent, AgentDocument } from "../../types/agent";
import { createHighlightRules, getMissingAttributes, getUnusedAttributes } from "../../utils/agentUtils";
import { getEntity, handleShowEntity, isPersistableEntity } from "../../utils/domainModelUtils";
import {
    handleAgentChangeValue,
    handleEditModelSettings,
    handleSelectEntity,
    handleSelectModel,
    handleShowModel,
    handleValidateAgent,
} from "./agentHandlers";

import { mendixCloudGenAIIconBase64 } from "../../icons/modelIcons";
import { ToolValidationState } from "../../types/tool";
import { InfoBanner, WarningBanner } from "../components/Banner";
import { BoldText } from "../components/elements/text";
import GroupBox from "../components/GroupBox";
import { ContentColumn } from "../components/PageContainers";
import TextAreaLabeled from "../components/TextAreaLabeled";
import TextInputWithButton from "../components/TextInputWithButton";
import { handleValidateKnowledgebaseTool } from "../tool/knowledgebaseToolHandlers";
import { handleValidateTool } from "../tool/toolHandlers";
import KnowledgebaseToolsTable from "./knowledgebaseToolsTable";
import { Output } from "./output";
import Playground from "./playground";
import ToolsTable from "./toolsTable";

interface Agentprops {
    agentDocument: AgentDocument;
    isRuntimeConnected: boolean;
    showUnsavedChangesWarning: boolean;
    studioPro: StudioProApi;
    updateStudioProDocument: (agent: Agent) => Promise<void>;
}

export type ValidationInfo = {
    isValidModel: true | string;
    isValidEntity: true | string;
    isValidUserPrompt: true | string;
    isValidToolChoice: true | string;
    missingAttributes: string[];
    unusedAttributes: string[];
};

const initialValidationInfo: ValidationInfo = {
    isValidModel: true,
    isValidEntity: true,
    isValidUserPrompt: true,
    isValidToolChoice: true,
    missingAttributes: [],
    unusedAttributes: [],
};

const AgentEditor: React.FC<Agentprops> = ({
    agentDocument: { name: agentName, contents: loadedAgent, $ID: documentId },
    isRuntimeConnected,
    showUnsavedChangesWarning,
    studioPro,
    updateStudioProDocument,
}) => {
    const [isLoaded, setIsLoaded] = useState(false);
    const [validationInfo, setValidationInfo] = useState(initialValidationInfo);
    const [entityIcon, setEntityIcon] = useState<React.ReactElement | undefined>(undefined);
    const [agent, setAgent] = useState(loadedAgent);
    const [hideUnusedAttributes, setHideUnusedAttributes] = useState(false);
    const [toolValidations, setToolValidations] = useState<Map<string, ToolValidationState>>(new Map());
    const [knowledgebaseToolValidations, setKnowledgebaseToolValidations] = useState<Map<string, ToolValidationState>>(
        new Map()
    );
    const theme = useTheme();

    const {
        data: response,
        isError: isActionError,
        error: actionError,
        isPending: isActionExecuting,
        execute: executeAction,
    } = useTestAction(studioPro, documentId, isRuntimeConnected);

    // Ref for debouncing document updates
    const debounceTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        validateAgent(loadedAgent).then((v) => setValidationInfo(v));
        getEntityIcon(studioPro, loadedAgent.entity?.qualifiedName).then((e) => setEntityIcon(e));
        setAgent(loadedAgent);
        setIsLoaded(true);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Sync internal agent state when the parent re-fetches the document (e.g. after an external rename)
    useEffect(() => {
        if (isLoaded) {
            setAgent(loadedAgent);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [loadedAgent]);

    // Cleanup debounce timeout on unmount
    useEffect(() => {
        return () => {
            if (debounceTimeout.current) {
                clearTimeout(debounceTimeout.current);
            }
        };
    }, []);

    useEffect(() => {
        const updateEntityIcon = async () => {
            const icon = await getEntityIcon(studioPro, agent.entity?.qualifiedName);
            setEntityIcon(icon);
        };

        if (isLoaded) {
            updateEntityIcon();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [studioPro, agent.entity?.qualifiedName]);

    useEffect(() => {
        const validateTools = async () => {
            const validationTasks: Promise<void>[] = [];

            if (agent.tools && agent.tools.length > 0) {
                // Set all tools to syncing state
                const syncingStates = new Map<string, ToolValidationState>();
                agent.tools.forEach((tool) => {
                    syncingStates.set(tool.id, "syncing");
                });
                setToolValidations(syncingStates);

                validationTasks.push(
                    Promise.all(
                        agent.tools.map(async (tool) => {
                            const validationResult = await handleValidateTool("document", tool, agent, studioPro);
                            return {
                                id: tool.id,
                                state:
                                    validationResult === true
                                        ? ("valid" as ToolValidationState)
                                        : ("invalid" as ToolValidationState),
                            };
                        })
                    ).then((validationResults) => {
                        const newValidations = new Map(validationResults.map((r) => [r.id, r.state]));
                        setToolValidations(newValidations);
                    })
                );
            }

            if (agent.knowledgebaseTools && agent.knowledgebaseTools.length > 0) {
                const syncingStates = new Map<string, ToolValidationState>();
                agent.knowledgebaseTools.forEach((tool) => {
                    syncingStates.set(tool.id, "syncing");
                });
                setKnowledgebaseToolValidations(syncingStates);

                validationTasks.push(
                    Promise.all(
                        agent.knowledgebaseTools.map(async (tool) => {
                            const validationResult = await handleValidateKnowledgebaseTool(
                                "document",
                                tool,
                                agent,
                                studioPro
                            );
                            return {
                                id: tool.id,
                                state:
                                    validationResult === true
                                        ? ("valid" as ToolValidationState)
                                        : ("invalid" as ToolValidationState),
                            };
                        })
                    ).then((validationResults) => {
                        const newValidations = new Map(validationResults.map((r) => [r.id, r.state]));
                        setKnowledgebaseToolValidations(newValidations);
                    })
                );
            }

            await Promise.all(validationTasks);
        };

        if (isLoaded) {
            validateTools();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isLoaded]);

    // When tools change after initial load, handle new/edited tools
    // Store tool document values separately since tool objects can be mutated
    const prevToolsRef = useRef<Map<string, string>>(new Map());
    const prevKnowledgebaseToolsRef = useRef<Map<string, string>>(new Map());

    useEffect(() => {
        if (isLoaded && agent.tools) {
            const prevTools = prevToolsRef.current;
            const currentTools = new Map<string, string>();

            // First, build the current tool map
            agent.tools.forEach((tool) => {
                currentTools.set(tool.id, tool.document.qualifiedName);
            });

            // Then update validation state
            setToolValidations((prevToolValidations) => {
                const updated = new Map(prevToolValidations);

                agent.tools?.forEach((tool) => {
                    if (!prevToolValidations.has(tool.id)) {
                        // New tool - set to valid
                        updated.set(tool.id, "valid");
                    } else {
                        // Check if tool was edited (document qualified name changed)
                        const prevTool = prevTools.get(tool.id);
                        const currentTool = currentTools.get(tool.id);
                        if (prevTool !== undefined && currentTool !== undefined && prevTool !== currentTool) {
                            // Tool was edited and validated via popup - set to valid
                            updated.set(tool.id, "valid");
                        }
                    }
                });

                return updated;
            });

            // Finally, update the ref for next time
            prevToolsRef.current = currentTools;
        }
    }, [agent.tools, isLoaded]);

    useEffect(() => {
        if (isLoaded && agent.knowledgebaseTools) {
            const prevTools = prevKnowledgebaseToolsRef.current;
            const currentTools = new Map<string, string>();

            agent.knowledgebaseTools.forEach((tool) => {
                currentTools.set(tool.id, tool.document.qualifiedName);
            });

            setKnowledgebaseToolValidations((prevToolValidations) => {
                const updated = new Map(prevToolValidations);

                agent.knowledgebaseTools?.forEach((tool) => {
                    if (!prevToolValidations.has(tool.id)) {
                        // New tool - set to valid
                        updated.set(tool.id, "valid");
                    } else {
                        // Check if tool was edited (document qualified name changed)
                        const prevTool = prevTools.get(tool.id);
                        const currentTool = currentTools.get(tool.id);
                        if (prevTool !== undefined && currentTool !== undefined && prevTool !== currentTool) {
                            // Tool was edited and validated via popup - set to valid
                            updated.set(tool.id, "valid");
                        }
                    }
                });

                return updated;
            });

            prevKnowledgebaseToolsRef.current = currentTools;
        }
    }, [agent.knowledgebaseTools, isLoaded]);

    useEffect(() => {
        const triggerValiation = async () => {
            const validationInfo = await validateAgent(agent);
            setValidationInfo(validationInfo);
        };

        if (isLoaded) {
            triggerValiation();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [studioPro, agent]);

    const highlightRules = useMemo(() => createHighlightRules(agent.variables, theme), [agent.variables, theme]);

    // Debounced handlers for text fields
    const onTextAreaChange = (field: keyof Agent) => (value: string) => {
        const agentWithUpdatedField: Agent = { ...agent, [field]: value };
        setAgent(agentWithUpdatedField);
        if (debounceTimeout.current) {
            clearTimeout(debounceTimeout.current);
        }
        debounceTimeout.current = setTimeout(async () => {
            const updatedAgent = await handleAgentChangeValue(
                studioPro,
                field,
                agentWithUpdatedField,
                updateStudioProDocument,
                value
            );
            setAgent(updatedAgent);
        }, 300);
    };

    //Handlers for selection buttons
    const selectEntity = async () => {
        const updatedAgent = await handleSelectEntity(studioPro, agent, updateStudioProDocument);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    };

    const selectModel = async () => {
        const updatedAgent = await handleSelectModel(studioPro, agent, updateStudioProDocument);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    };

    const showModel = async () => {
        if (agent.model) {
            handleShowModel(studioPro, agent.model);
        }
    };

    const showEntity = async () => {
        if (!agent.entity) {
            return;
        }

        handleShowEntity(studioPro, agent.entity.qualifiedName);
    };

    const editModelSettings = async () => {
        const updatedAgent = await handleEditModelSettings(studioPro, componentName, agent, updateStudioProDocument);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    };

    //Page-specific UI functions
    const getEntityIcon = async (
        studioPro: StudioProApi,
        entityName?: string
    ): Promise<React.ReactElement | undefined> => {
        if (!entityName) {
            return undefined;
        }
        const entity = await getEntity(studioPro, entityName);
        if (!entity) {
            return undefined;
        }
        const isPersistable = await isPersistableEntity(entity, studioPro);
        if (isPersistable === undefined) {
            return undefined;
        }
        return isPersistable ? <EntityIcon /> : <EntityNonPersistableIcon />;
    };

    const modelSettings = useMemo(() => {
        let modelSettingsString = "";
        if (agent.maxTokens !== undefined) {
            modelSettingsString += "Max tokens: " + agent.maxTokens.toLocaleString(navigator.language);
        }
        if (agent.temperature !== undefined) {
            if (modelSettingsString.length > 0) {
                modelSettingsString += ", ";
            }
            modelSettingsString +=
                "Temperature: " +
                agent.temperature.toLocaleString(navigator.language, {
                    minimumFractionDigits: 1,
                    maximumFractionDigits: 2,
                });
        }
        if (agent.topP !== undefined) {
            if (modelSettingsString.length > 0) {
                modelSettingsString += ", ";
            }
            modelSettingsString +=
                "Top P: " +
                agent.topP.toLocaleString(navigator.language, { minimumFractionDigits: 1, maximumFractionDigits: 2 });
        }
        return modelSettingsString;
    }, [agent.temperature, agent.maxTokens, agent.topP]);

    const validateAgent = async (agent: Agent): Promise<ValidationInfo> => {
        return {
            isValidModel: await handleValidateAgent("model", studioPro, agent),
            isValidEntity: await handleValidateAgent("entity", studioPro, agent),
            isValidUserPrompt: await handleValidateAgent("userPrompt", studioPro, agent),
            missingAttributes: await getMissingAttributes(studioPro, agent),
            unusedAttributes: await getUnusedAttributes(studioPro, agent),
            isValidToolChoice: await handleValidateAgent("toolChoice", studioPro, agent),
        };
    };

    const renderGeneralInfo = () => (
        <GroupBox label="General">
            <TextInputWithButton
                ariaLabel="Model"
                label="Model"
                value={agent.model?.qualifiedName || ""}
                icon={agent.model ? mendixCloudGenAIIconBase64 : undefined}
                buttonCaption="Select..."
                onClick={selectModel}
                validate={() => validationInfo.isValidModel}
                buttonCaptionSecondary={agent.model ? "Show" : undefined}
                onClickSecondary={agent.model ? showModel : undefined}
            />
            <TextInputWithButton
                ariaLabel="Settings"
                label="Model settings"
                value={modelSettings}
                buttonCaption="Edit"
                onClick={editModelSettings}
                validate={undefined}
            />
            <TextArea
                label="Documentation"
                aria-label="Documentation"
                value={agent.description}
                onChange={onTextAreaChange("description")}
                rows={3}
            />
            <TextInputWithButton
                ariaLabel="Context entity"
                label="Context entity"
                value={agent.entity?.qualifiedName || ""}
                icon={entityIcon}
                onClick={selectEntity}
                buttonCaption="Select..."
                validate={() => validationInfo.isValidEntity}
                buttonCaptionSecondary={agent.entity ? "Show" : undefined}
                onClickSecondary={agent.entity ? showEntity : undefined}
            />
            {agent.entity && validationInfo.missingAttributes.length > 0 && (
                <WarningBanner>
                    <BoldText>{`The following attributes cannot be found in ${agent.entity.qualifiedName}:`}</BoldText>
                    <div>{validationInfo.missingAttributes.map((attr) => `{{${attr}}}`).join(", ")}</div>
                </WarningBanner>
            )}
            {agent.entity && validationInfo.unusedAttributes.length > 0 && !hideUnusedAttributes && (
                <InfoBanner onClose={() => setHideUnusedAttributes(true)}>
                    <BoldText>{`The following attributes are found in ${agent.entity?.qualifiedName}, but are not in use.`}</BoldText>
                    <div>{validationInfo.unusedAttributes.map((attr) => `{{${attr}}}`).join(", ")}</div>
                </InfoBanner>
            )}
        </GroupBox>
    );

    const renderSystemPrompt = () => (
        <GroupBox label="System prompt">
            <TextAreaLabeled
                ariaLabel="System prompt"
                value={agent.systemPrompt}
                onChange={onTextAreaChange("systemPrompt")}
                highlightRules={highlightRules}
                placeholder="Enter the system prompt here. Outline the agent's goals, constraints and behavior. To create variables, use double curly brackets, like {{VariableName}}."
            />
        </GroupBox>
    );

    const renderUserPrompt = () => (
        <GroupBox label="User prompt">
            <TextAreaLabeled
                ariaLabel="User prompt"
                value={agent.userPrompt || ""}
                onChange={onTextAreaChange("userPrompt")}
                highlightRules={highlightRules}
                validate={() => validationInfo.isValidUserPrompt}
                placeholder="Enter the user prompt here. Define the input from the user of the system that triggers the agent.To create variables, use double curly brackets, like {{VariableName}}."
            />
        </GroupBox>
    );

    const renderTools = () => (
        <ToolsTable
            agent={agent}
            studioPro={studioPro}
            componentName={componentName}
            updateStudioProDocument={updateStudioProDocument}
            onAgentChange={setAgent}
            toolValidations={toolValidations}
            agentValidationInfo={validationInfo}
        />
    );

    const renderPlayground = () => (
        <Playground
            variables={agent.variables}
            highlightRules={highlightRules}
            triggerTestAction={executeAction}
            isDisabled={isActionExecuting || showUnsavedChangesWarning}
            showUnsavedChangesWarning={showUnsavedChangesWarning}
        />
    );

    const renderKnowledgebaseTools = () => (
        <KnowledgebaseToolsTable
            agent={agent}
            studioPro={studioPro}
            componentName={componentName}
            updateStudioProDocument={updateStudioProDocument}
            onAgentChange={setAgent}
            knowledgebaseToolValidations={knowledgebaseToolValidations}
        />
    );

    const renderOutput = () => (
        <Output
            agentName={agentName}
            response={response}
            isLoading={isActionExecuting}
            isError={isActionError}
            error={actionError}
        />
    );

    return (
        <>
            <ContentColumn>
                {renderGeneralInfo()}
                {renderSystemPrompt()}
                {renderUserPrompt()}
                {renderTools()}
                {renderKnowledgebaseTools()}
            </ContentColumn>
            <ContentColumn>
                {renderPlayground()}
                {renderOutput()}
            </ContentColumn>
        </>
    );
};

export default AgentEditor;
