import { ChevronDownIcon, ChevronRightIcon } from "@src/icons";
import { ReactNode, useId, useState } from "react";

import styled from "styled-components";

interface AccordionProps {
    title: string;
    children: ReactNode;
    defaultExpanded?: boolean;
}

const Header = styled.button`
    all: unset;
    display: flex;
    align-items: center;
    width: 100%;
    color: ${({ theme }) => theme.colorsTextPrimaryDefault};
    gap: 4px;
`;

const Content = styled.div`
    padding-bottom: 8px;
`;

/**
 * Accordion component that shows/hides its children based on a collapsed state.
 * Accessible via keyboard and screen readers using aria-expanded and aria-controls.
 */
const Accordion = ({ title, children, defaultExpanded = false }: AccordionProps) => {
    const [isExpanded, setIsExpanded] = useState(defaultExpanded);
    const contentId = useId();

    return (
        <div>
            <Header aria-expanded={isExpanded} aria-controls={contentId} onClick={() => setIsExpanded((prev) => !prev)}>
                {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                {title}
            </Header>
            {isExpanded && (
                <Content id={contentId} role="region" aria-label={title}>
                    {children}
                </Content>
            )}
        </div>
    );
};

export default Accordion;
