import { Icon } from "@mendix/ide-ui-components/icon/Icon";
import styled from "styled-components";

import { agentIconBase64 } from "../../../icons/agentIcons";
import { DivFlexRow } from "../../components/elements/formelements";
import { BoldText } from "../../components/elements/text";

interface HeaderProps {
    name: string;
    timestamp: number;
}

const TestTimestamp = styled.div`
    margin-left: auto;
    color: ${({ theme }) => theme.colorsTextSecondaryDefault};
`;

const Header: React.FC<HeaderProps> = ({ name, timestamp }) => (
    <DivFlexRow>
        <Icon src={agentIconBase64} />
        <BoldText>{name}</BoldText>
        <TestTimestamp>{new Date(timestamp).toLocaleString()}</TestTimestamp>
    </DivFlexRow>
);

export default Header;
