import { useEffect, useRef, useState } from "react";

import { CheckIcon } from "@mendix/ide-icons/CheckIcon";
import { CopyIcon } from "@mendix/ide-icons/CopyIcon";
import { IconButton } from "@mendix/ide-ui-components/button/IconButton";
import styled from "styled-components";

import { ClockIcon, TokenIcon } from "@src/icons";
import { getDurationString } from "../../../utils/timeUtils";
import { isDarkTheme } from "../../../utils/userPreferences";
import { DivFlexRow } from "../../components/elements/formelements";

const MetadataText = styled.span`
    font-size: 10px;
    color: ${({ theme }) => (isDarkTheme(theme) ? theme.colorsAccentWhite : theme.colorsTextSecondaryDefault)};
`;

const ActionsContainer = styled(DivFlexRow)`
    margin-left: auto;
`;

const CopyToClipboardText = styled.span`
    align-self: center;
    font-size: 10px;
    color: ${({ theme }) => theme.colorsTextSecondaryDefault};
`;

interface MetadataProps {
    totalTokens: number;
    requestTokens: number;
    responseTokens: number;
    duration: number;
    handleCopyClick: () => void;
}

const Metadata: React.FC<MetadataProps> = ({
    totalTokens,
    requestTokens,
    responseTokens,
    duration,
    handleCopyClick,
}) => {
    const [copied, setCopied] = useState(false);

    const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        return () => {
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }
        };
    }, []);

    const handleClick = () => {
        handleCopyClick();
        setCopied(true);
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
        }
        timeoutRef.current = setTimeout(() => setCopied(false), 1000);
    };

    return (
        <DivFlexRow alignItems="center">
            <DivFlexRow gap={4}>
                <TokenIcon />
                {totalTokens && <MetadataText>{totalTokens.toLocaleString(navigator.language)}</MetadataText>}
            </DivFlexRow>
            {requestTokens && responseTokens && (
                <MetadataText>{`(${requestTokens.toLocaleString(navigator.language)} / ${responseTokens.toLocaleString(navigator.language)})`}</MetadataText>
            )}
            <DivFlexRow gap={4}>
                <ClockIcon />
                {duration && <MetadataText>{getDurationString(duration)}</MetadataText>}
            </DivFlexRow>
            <ActionsContainer>
                <IconButton icon={copied ? <CheckIcon /> : <CopyIcon />} onPress={handleClick} />
                {copied && <CopyToClipboardText>Copied to clipboard</CopyToClipboardText>}
            </ActionsContainer>
        </DivFlexRow>
    );
};

export default Metadata;
