import { Link } from "@mendix/ide-ui-components/link/Link";
import { ErrorWithLink } from "@src/types/generic";
import { Response } from "../../../types/playground";
import { WarningBanner } from "../../components/Banner";
import { BoldText } from "../../components/elements/text";
import GroupBox from "../../components/GroupBox";
import LoadingDots from "../../components/LoadingDots";
import MarkdownRenderer from "../../components/MarkdownRenderer";
import Header from "./Header";
import Metadata from "./Metadata";
import NoResponse from "./NoResponse";
import ReferencesAndTools from "./ReferencesAndTools";

interface OutputProps {
    agentName: string;
    error?: ErrorWithLink;
    isError: boolean;
    isLoading: boolean;
    response?: Response;
}

const Output: React.FC<OutputProps> = ({ agentName, response, isLoading, isError, error }) => {
    const copyToClipboard = () => {
        if (!response) return;
        navigator.clipboard.writeText(response.responseText);
    };

    const renderOutputContent = () => {
        if (isError && error) {
            return (
                <WarningBanner>
                    <BoldText>Test execution failed</BoldText>
                    <div>{error.message}</div>
                    {error.link && (
                        <div>
                            For more information, please visit{" "}
                            <Link href={error.link} target="_blank" rel="noopener noreferrer">
                                MxDocs
                            </Link>
                            .
                        </div>
                    )}
                </WarningBanner>
            );
        }

        if (isLoading) {
            return <LoadingDots />;
        }

        if (!response) {
            return <NoResponse />;
        }

        return (
            <>
                <Header name={agentName} timestamp={response.receivedAt} />
                <MarkdownRenderer content={response.responseText} />
                <Metadata
                    totalTokens={response.totalTokens}
                    requestTokens={response.requestTokens}
                    responseTokens={response.responseTokens}
                    duration={response.durationMilliseconds}
                    handleCopyClick={copyToClipboard}
                />
                {response.tools && response.tools.length > 0 && <ReferencesAndTools tools={response.tools} />}
            </>
        );
    };

    return <GroupBox label="Output">{renderOutputContent()}</GroupBox>;
};

export default Output;
